function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => v < 1 || v > 1000000000)) return 'Each value is between 1 and 10^9.';
  if (k < 0 || k > 1000000000) return 'k is between 0 and 10^9.';
  return null;
}

