function maxDistinctElements(nums, k) {
  nums.sort((a, b) => a - b);
  let distinct = 0;
  let last = -Infinity;
  for (const num of nums) {
    const value = Math.max(last + 1, num - k);
    if (value <= num + k) {
      distinct++;
      last = value;
    }
  }
  return distinct;
}

