function maxDistinctElements(nums, k) {
  // The answer is a maximum matching between elements and integers, where element i may take any
  // integer in [nums[i] - k, nums[i] + k]: one element per distinct final value is a matching, and
  // unmatched elements can keep any value in range. Kuhn's augmenting paths find the matching; a
  // search stops at the first free integer, so it tries at most n + 1 integers even for huge k.
  const owner = new Map();
  const assign = (i, visited) => {
    for (let v = nums[i] - k; v <= nums[i] + k; v++) {
      if (!owner.has(v)) {
        owner.set(v, i);
        return true;
      }
      const j = owner.get(v);
      if (!visited.has(j)) {
        visited.add(j);
        if (assign(j, visited)) {
          owner.set(v, i);
          return true;
        }
      }
    }
    return false;
  };
  let matched = 0;
  for (let i = 0; i < nums.length; i++) if (assign(i, new Set([i]))) matched++;
  return matched;
}

