function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'small') {
    const n = int(1, 8);
    const top = rand() < 0.7 ? 6 : 40;
    const nums = Array.from({ length: n }, () => int(1, top));
    const k = rand() < 0.85 ? int(0, 3) : rand() < 0.5 ? int(4, 20) : 1000000000;
    return [nums, k];
  }
  const n = 2000;
  const mode = int(0, 3);
  // Crowded small values, spread-out values, one repeated value, and values packed near the top.
  if (mode === 0) return [Array.from({ length: n }, () => int(1, 1000)), int(0, 3)];
  if (mode === 1) return [Array.from({ length: n }, () => int(1, 1000000000)), int(0, 1000000000)];
  if (mode === 2) return [new Array(n).fill(int(1, 1000000000)), int(0, 1500)];
  return [Array.from({ length: n }, () => int(999999000, 1000000000)), int(0, 2)];
}
